async function save(fields){if(local()){state.project=await patchDevice(state.project,fields);deviceProjects=await listDevice();markActivity('Draft saved on this device.');return state.project;}const data=await api(`/api/projects/${encodeURIComponent(state.project.id)}`,{method:'PATCH',body:{...fields,expectedVersion:state.project.version}});state.project=projectFrom(data);markActivity('Project changes saved.');return state.project;}
async function loadProject(id){if(state.project?.id!==id&&!departmentNavigationAllowed())return;if(id.startsWith('device-')){const project=await getDevice(id);if(!project)return toast('That device draft is unavailable.');state.project=project;state.assets=await loadDeviceAssets(id);state.shot=project.shots[0]?.id||null;state.messages=project.notes||[];state.refs=[];state.skill=null;state.skills=localSkills;remember(id);studioPageId='workspace';setStudioHash('project/'+id);render();return;}const previous=state.project;try{const data=await api(`/api/projects/${encodeURIComponent(id)}`);const candidate=projectFrom(data);const [assets,approvals]=await Promise.all([api(`/api/projects/${encodeURIComponent(id)}/assets`),api(`/api/projects/${encodeURIComponent(id)}/approvals`)]);state.project=candidate;state.assets=list(assets,'assets');state.approvals=list(approvals,'approvals');state.shot=state.project.shots?.[0]?.id||null;state.messages=state.project.notes||[];state.refs=[];state.skill=null;remember(id);studioPageId='workspace';setStudioHash('project/'+id);render();}catch(error){state.project=previous;toast(error.message);}}
function render(){document.body.classList.add('frozen-studio');$('#notice').classList.toggle('notice-important',state.project?.importState?.status==='awaiting_media');document.body.classList.toggle('frozen-project',studioPageId==='workspace'&&!!state.project);disposeMusicVideo();disposeAnimatic();document.body.classList.remove('studio-menu-open');if($('#project-costs'))$('#project-costs').hidden=!state.project;const cloud=$('#cloud-save');cloud.hidden=!local();cloud.disabled=migrationBusy;cloud.textContent=migrationBusy?'Saving…':'Save to workspace';cloud.setAttribute('aria-label',migrationBusy?'Saving draft to workspace':'Save to workspace');cloud.onclick=saveToWorkspace;$('#mode').textContent=local()?'On this device':state.config.mode==='demo'?'Local demo':'Workspace';document.body.classList.toggle('in-studio',studioPageId==='workspace'&&['production','edit','export'].includes(stage())&&!!state.project);$('#notice').textContent=local()?'Draft saved on this device · not uploaded to your account':state.config.mode==='demo'?'Local development workspace · no paid generation.':state.project?.importState?.status==='awaiting_media'?'This cloud copy has pending references. Reopen its device draft and choose Save to workspace to resume.':!state.config.user?'Create with your own references. Sign in to save your projects and media.':''; $('#project-name').textContent=state.project?.title||'Your creative workspace';$('#studio-menu-button').setAttribute('aria-expanded','false');$('#studio-menu-button').setAttribute('aria-controls',studioPageId==='workspace'&&state.project?'rail':'studio-sidebar');studioLibraryEpoch++;if(studioPageId==='home'||studioPageId==='create')return renderWelcome();if(studioPageId!=='workspace')return renderStudioSection();if(!state.project)return renderWelcome();renderWorkspace();}
function allStudioProjects(){const projects=new Map([...deviceProjects,...state.projects].map(p=>[p.id,p]));if(state.project)projects.set(state.project.id,state.project);return [...projects.values()].sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));}
function setStudioHash(route){if(studioBooting)return;if(location.hash!=='#'+route)history.pushState(null,'','#'+route);}
