 if(studioPageId==='projects')content=projectsPage(projects);
 if(studioPageId==='assets')content=assetFilters(studioAssetTab,projects);
 if(studioPageId==='brand')content=`<header class="studio-page-head"><div><h1>Brand & characters</h1><p>Keep product, character, look and voice decisions in their versioned project library.</p></div></header><div class="panel"><h2>Character references</h2><p>Browse your saved identity references across projects.</p><a href="#assets/characters" data-studio-route="assets/characters">Open Characters →</a></div><div class="panel"><h2>Project libraries</h2><p>Open a project’s cast and world to review its products, characters, references and approvals.</p>${projects.map(p=>`<div class="resume-row"><strong>${esc(p.title)}</strong><button data-open-cast="${esc(p.id)}">Open library</button></div>`).join('')||'<a href="#create" data-studio-route="create">Create your first project →</a>'}</div>`;
