window.addEventListener('beforeunload',event=>{if(musicTreatmentHasUnsaved(state.project?.id)||musicVideoHasUnsaved()||departmentDrafts.has(state.project?.id)||storyboardDrafts.has(state.project?.id)||referenceDrafts.has(state.project?.id)||frameDrafts.has(state.project?.id)){event.preventDefault();event.returnValue='';}});
