function departmentDocumentHTML(document){return `<p class="department-summary">${esc(document.summary)}</p><details class="department-details"><summary>Requirements, choices & handoffs</summary><p class="small muted">${esc(({required:'Required',conditional:'Conditional',not_applicable:'Not applicable'})[document.applicability]||'Needs review')} · ${esc(document.rationale)}</p>${document.requirements?.length?`<h4>Requirements</h4>${document.requirements.map(r=>`<p><strong>${esc(r.label)}</strong><br>${esc(r.direction)}</p>`).join('')}`:''}${document.choices?.length?`<h4>Creative choices</h4>${document.choices.map(c=>`<p><strong>${esc(c.label)}</strong> <span class="small muted">${esc(({proposed:'Proposed',needs_decision:'To decide',user_selected:'Your choice'})[c.status]||'Proposed')}</span><br>${esc(c.value)}</p>`).join('')}`:''}${document.handoffs?.length?`<h4>Department handoffs</h4>${document.handoffs.map(h=>`<p><strong>${esc(departmentLabels[h.toDepartmentId]||h.toDepartmentId)}</strong><br>${esc(h.deliverable)}</p>`).join('')}`:''}${document.checks?.length?`<h4>Review before production</h4><ul>${document.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:''}</details>`;}
function departmentDocumentKey(value){if(Array.isArray(value))return '['+value.map(departmentDocumentKey).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(key=>JSON.stringify(key)+':'+departmentDocumentKey(value[key])).join(',')+'}';return JSON.stringify(value);}
function departmentFieldOptions(document){const fields=[{key:'summary',label:'Plan summary',value:document.summary,max:4000},{key:'rationale',label:'Why this department is needed',value:document.rationale,max:2000},{key:'applicability',label:'Applicability',value:document.applicability}];(document.requirements||[]).forEach((r,i)=>fields.push({key:`requirements.${i}.direction`,label:r.label,value:r.direction,max:4000}));(document.choices||[]).forEach((c,i)=>fields.push({key:`choices.${i}.value`,label:`Choice · ${c.label}`,value:c.value,status:c.status,max:2000}));(document.checks||[]).forEach((value,i)=>fields.push({key:`checks.${i}`,label:`Review check ${i+1}`,value,max:1000}));return fields;}
function departmentEditorHTML(draft){if(!draft)return '';if(draft.mode==='repair')return departmentRepairEditorHTML(draft);if(draft.mode==='revision')return departmentRevisionEditorHTML(draft);const current=currentDepartmentPlan(state.project,draft.departmentId);if(!current)return '<p class="pending">This department is unavailable. Cancel this edit and refresh the project.</p>';const options=departmentFieldOptions(current.document),dirty=String(draft.value??'')!==String(options.find(f=>f.key===draft.field)?.value??'')||draft.recordChoice===true;return `<form id="department-editor" class="department-focused-editor"><h3>Edit ${esc(departmentLabels[draft.departmentId])}</h3><p class="small muted">Only this department’s direction is edited. Earlier versions remain recorded; affected downstream plans need review.</p><label>What to change<select name="field" ${dirty?'disabled':''}>${options.map(f=>`<option value="${esc(f.key)}" ${draft.field===f.key?'selected':''}>${esc(f.label)}</option>`).join('')}</select></label>${draft.field==='applicability'?`<label>Applicability<select name="value">${[['required','Required'],['conditional','Conditional'],['not_applicable','Not applicable']].map(([value,label])=>`<option value="${value}" ${draft.value===value?'selected':''}>${label}</option>`).join('')}</select></label>`:`<label>Updated direction<textarea name="value" rows="5" maxlength="${esc(options.find(f=>f.key===draft.field)?.max||4000)}" required>${esc(draft.value)}</textarea></label>`}${draft.field.startsWith('choices.')?`<label class="department-check"><input type="checkbox" name="recordChoice" ${draft.recordChoice?'checked':''}><span>Record this as my creative choice. This does not approve an actor, look image or voice recording.</span></label>`:''}<div class="actions"><button type="submit" class="primary">Save department version</button><button type="button" id="cancel-department-edit">Cancel</button></div></form>`;}
const departmentOpenUnits=new Map();
