async function referenceAction(action){if(referenceBusy||referenceGenerationBusy)return;referenceBusy=true;const controls=Array.from(document.querySelectorAll('#main button,#main input,#main textarea,#main select,.top nav button'),node=>({node,disabled:node.disabled}));controls.forEach(({node})=>node.disabled=true);try{await action();}catch(error){const status=$('#reference-production-status'),editor=$('#reference-editor-status');if(status)status.textContent=error.message;if(editor)editor.textContent=error.message;else if(status)status.scrollIntoView({block:'nearest'});else toast(error.message);}finally{referenceBusy=false;controls.forEach(({node,disabled})=>{if(node.isConnected)node.disabled=disabled;});}}
